/* --- packages/ui/components/stat/stat.js --- */
/* Stat count-up: [data-corn-count] animates once when first visible. */
(function (Corn) {
  'use strict';

  function format(n, decimals) {
    return n.toLocaleString('zh-CN', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
  }

  function run(el) {
    var target = parseFloat(el.getAttribute('data-corn-count'));
    if (isNaN(target)) return;
    var decimals = parseInt(el.getAttribute('data-decimals') || '0', 10);
    var suffix = el.getAttribute('data-suffix') || '';
    var card = el.closest('.corn-stat');
    if (card) card.classList.add('is-counting');
    if (Corn.reducedMotion()) {
      el.textContent = format(target, decimals) + suffix;
      return;
    }
    var start = performance.now();
    var dur = 1100;
    (function tick(now) {
      var t = Math.min(1, (now - start) / dur);
      var eased = 1 - Math.pow(1 - t, 3);
      el.textContent = format(target * eased, decimals) + suffix;
      if (t < 1) requestAnimationFrame(tick);
    })(start);
  }

  Corn.define('stat-count', '[data-corn-count]', function (el) {
    el.setAttribute('aria-label', el.textContent.trim());
    if (!('IntersectionObserver' in window)) return run(el);
    var io = new IntersectionObserver(function (entries) {
      if (entries[0].isIntersecting) {
        io.disconnect();
        run(el);
      }
    }, { threshold: 0.4 });
    io.observe(el);
  });
})(window.Corn);

/* --- packages/ui/components/code/code.js --- */
/* Copy button: [data-corn-copy="#selector"] copies the target's text. */
(function (Corn) {
  'use strict';

  function fallback(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.cssText = 'position:fixed;opacity:0';
    document.body.appendChild(ta);
    ta.select();
    var ok = false;
    try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
    ta.remove();
    return ok;
  }

  Corn.copyText = function (text) {
    if (navigator.clipboard && window.isSecureContext) {
      return navigator.clipboard.writeText(text).then(function () { return true; }, function () { return fallback(text); });
    }
    return Promise.resolve(fallback(text));
  };

  Corn.define('copy', '[data-corn-copy]', function (btn) {
    var label = btn.textContent;
    var timer = 0;
    btn.addEventListener('click', function () {
      var target = document.querySelector(btn.getAttribute('data-corn-copy'));
      var text = target ? target.textContent : '';
      (text ? Corn.copyText(text) : Promise.resolve(false)).then(function (ok) {
        clearTimeout(timer);
        btn.setAttribute('data-state', ok ? 'ok' : 'error');
        btn.textContent = ok ? '已复制' : '复制失败';
        timer = setTimeout(function () {
          btn.removeAttribute('data-state');
          btn.textContent = label;
        }, 1800);
      });
    });
  });
})(window.Corn);

/* --- packages/ui/components/toast/toast.js --- */
/* Toast: Corn.toast(options) + declarative [data-corn-toast] triggers.
   Lifetime is driven by the timer bar's animationend, so hover/focus pause
   (CSS animation-play-state) also pauses the dismissal. */
